/**
 * HELP DESTINATIONS (F-B "Kalimat Pembuka per Tujuan")
 *
 * Static, source-cited checklists per help pathway. NOTHING in this file is
 * generated by a model; it is hand-written from
 * docs/research/RISET_FITUR_DAN_GAP_2026-10-13.md §2.2 and carries the date
 * the sources were last checked.
 *
 * Rules:
 *  - Every checklist item either cites at least one source below, or is
 *    explicitly marked `unverified: true` and rendered as "saran umum" /
 *    "belum diverifikasi" in the UI.
 *  - Facts the research doc flagged [BELUM DIVERIFIKASI] are left out on
 *    purpose: Healing119 WhatsApp number and yearly contact volume, BPJS
 *    referral validity period (3 months), private counselling prices,
 *    clinical-psychologist ratio.
 *  - Hours and availability are stated the way the official source states
 *    them; no "24 jam" claim unless an official page says so.
 */

export type HelpDestinationId = 'fktp' | 'psikolog' | 'healing119' | 'kampus';

export interface HelpDestinationSource {
  id: string;
  /** Short human label, e.g. "Kemenkes, 7 Agu 2025". */
  label: string;
  url: string;
  /** 'official' = government/organisation page; 'media' = news; 'guide' = NGO guidance (non-Indonesian context). */
  kind: 'official' | 'media' | 'guide';
  /** YYYY-MM-DD the page was read. */
  accessedOn: string;
}

export interface HelpChecklistItem {
  text: string;
  /** Ids from `sources`. Empty only when `unverified` is true. */
  sourceIds: string[];
  /** General advice without a verifiable Indonesian source. Shown with a label, never as fact. */
  unverified?: boolean;
}

export interface HelpDestination {
  id: HelpDestinationId;
  /** Chip label, short. */
  label: string;
  /** One warm sentence explaining when this destination fits. */
  description: string;
  /** Who the user is speaking to, for the prompt and the template. */
  speakingTo: string;
  /** How the user usually opens, e.g. "Dok,". Empty when no vocative fits. */
  vocative: string;
  /** What the user wants from this destination; the only intent the model may add. */
  ask: string;
  checklist: HelpChecklistItem[];
  sources: HelpDestinationSource[];
  /** Honest caveat shown under the checklist. */
  caveat: string;
  /** YYYY-MM-DD the checklist facts were last checked against the sources. */
  verifiedOn: string;
}

