const BY_ID: ReadonlyMap<HelpDestinationId, HelpDestination> = new Map(HELP_DESTINATIONS.map((d) => [d.id, d]));

export function isHelpDestinationId(value: unknown): value is HelpDestinationId {
  return typeof value === 'string' && BY_ID.has(value as HelpDestinationId);
}

export function getHelpDestination(id: HelpDestinationId): HelpDestination {
  const found = BY_ID.get(id);
  if (!found) throw new Error(`Tujuan tidak dikenal: ${id}`);
  return found;
}
